def _decode() -> dict[str, Any]:
    value = json.loads(zlib.decompress(base64.b85decode(_LITERAL.encode())).decode())
    if value["catalog_digest"] != CATALOG_DIGEST:
        raise RuntimeError("frozen SQLite catalog digest mismatch")
    inventory_digest = hashlib.sha256(
        json.dumps(value["inventory"], ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    if inventory_digest != CATALOG_DIGEST:
        raise RuntimeError("frozen SQLite inventory declaration digest mismatch")
    return value

CATALOG: dict[str, Any] = _decode()
INVENTORY: dict[str, Any] = CATALOG["inventory"]
GUARD_DDL = {item["name"]: item["sql"] for item in INVENTORY["sqlite_schema"] if item["name"] in REPAIRABLE_GUARDS}

def catalog_attestation() -> str:
    """Digest of the immutable product declaration, not a live database."""
    return hashlib.sha256(json.dumps(CATALOG, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest()

def construct_sql() -> tuple[str, ...]:
    """Literal target DDL in dependency order; auto-indexes remain table-owned."""
    objects = INVENTORY["sqlite_schema"]
    return tuple(item["sql"] for kind in ("table", "index", "trigger") for item in objects if item["type"] == kind and item["sql"] and item["name"] != "sqlite_sequence")
